<script setup lang="ts">
import {ref,watch} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;section?:string}>();const busy=ref(false),error=ref(''),message=ref('');
const evidence=ref({region:'阿拉山口',project_level:'乡镇级',basis:'现状/规划/建设/实测',measurement_period:'',measured_metrics:'',conclusion:'',source:'',status:'待补'});
const rows=ref<any[]>([{id:'demo',name:'示范区模型与实证记录',status:'待补',source:'',note:''},{id:'software_test',name:'软件测试报告',status:'已具备',source:'backend/测试记录',note:'以实际测试输出为准'},{id:'manual',name:'用户手册与安装说明',status:'待补',source:'',note:''},{id:'copyright',name:'软著代码清单与成果证明',status:'待补',source:'',note:''},{id:'acceptance',name:'任务书指标验收证据',status:'部分具备',source:'docs/与任务书对应记录',note:'性能与动态精度仍待验证'}]);
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function read(){if(!props.projectId)return;busy.value=true;try{const d=await api('/api/drafts/'+encodeURIComponent(props.section==='示范区实证'?'示范区实证':'成果与交付')+'?project_id='+encodeURIComponent(props.projectId));if(props.section==='示范区实证'&&d.values?.evidence)Object.assign(evidence.value,d.values.evidence);if(props.section!=='示范区实证'&&d.values?.rows)rows.value=d.values.rows}catch(e){error.value=String(e)}finally{busy.value=false}}
watch(()=>props.projectId,read,{immediate:true});
async function save(){busy.value=true;try{const d=await api('/api/drafts/成果与交付?project_id='+encodeURIComponent(props.projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:{rows:rows.value}})});message.value='交付清单已保存 · '+d.updated}catch(e){error.value=String(e)}finally{busy.value=false}}
async function saveEvidence(){busy.value=true;try{const d=await api('/api/drafts/示范区实证?project_id='+encodeURIComponent(props.projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:{evidence:evidence.value}})});message.value='示范区实证记录已保存 · '+d.updated}catch(e){error.value=String(e)}finally{busy.value=false}}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({project_id:props.projectId,rows:rows.value},null,2)],{type:'application/json'}));a.download='成果与交付清单.json';a.click()}
function downloadEvidence(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({project_id:props.projectId,evidence:evidence.value},null,2)],{type:'application/json'}));a.download='示范区实证记录.json';a.click()}
</script>
<template><article v-if="section==='示范区实证'"><h3>示范区实证记录</h3><p>分别记录现状、规划、建设和实测依据。实测结论必须有来源和时间，不用软件预测结果替代现场证据。</p><p v-if="error" class="error">{{error}}</p><p v-if="message" class="notice">{{message}}</p><label class="field">示范区域<input v-model="evidence.region"></label><label class="field">对象层级<input v-model="evidence.project_level"></label><label class="field">依据类型<input v-model="evidence.basis"></label><label class="field">实测时段<input v-model="evidence.measurement_period"></label><label class="field">实测指标<textarea v-model="evidence.measured_metrics"></textarea></label><label class="field">实证结论<textarea v-model="evidence.conclusion"></textarea></label><label class="field">证据来源<input v-model="evidence.source"></label><label class="field">状态<select v-model="evidence.status"><option>待补</option><option>部分具备</option><option>已具备</option><option>已验收</option></select></label><div class="actions"><button @click="saveEvidence" :disabled="busy">保存实证记录</button><button @click="downloadEvidence">导出 JSON</button><button @click="read" :disabled="busy">重新读取</button></div></article><article v-else><h3>成果与交付清单</h3><p>本页记录成果证据的实际状态、来源和缺口。状态由项目组维护，不因规划项或页面存在自动视为验收通过。</p><p v-if="error" class="error">{{error}}</p><p v-if="message" class="notice">{{message}}</p><div class="scroll"><table><tr><th>交付项</th><th>状态</th><th>证据来源</th><th>备注</th></tr><tr v-for="r in rows" :key="r.id"><td>{{r.name}}</td><td><select v-model="r.status"><option>待补</option><option>部分具备</option><option>已具备</option><option>已验收</option></select></td><td><input v-model="r.source"></td><td><input v-model="r.note"></td></tr></table></div><div class="actions"><button @click="save" :disabled="busy">保存交付清单</button><button @click="download">导出 JSON</button><button @click="read" :disabled="busy">重新读取</button></div></article></template>
<style scoped>.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e2eded}input,select{padding:7px;border:1px solid #c8dcdf;min-width:140px}.actions{display:flex;gap:10px;margin-top:16px}</style>


